import type {
  TBankAccountNumber,
  TUserId,
  TTransactionId,
} from "@/types";

import type {
  IAccount, 
  ITransaction, 
  TTransactionQuery,
  ILedger
} from "./internal";

export type CreateAccountInput = Omit<IAccount, "id" | "createdAt" | "updatedAt">;

export type TransferInput = Omit<ITransaction, "id" | "status" | "amount"> & {
